} from "/Users/jessearmand/Develop/realtime-persona/lib/memory/elevenlabs-conversation";
import { addMemories } from "/Users/jessearmand/Develop/realtime-persona/lib/memory/mem0-rest";

const USER = "tsubaki-e5d319f0-01e6-4b8c-b1f4-3bec67046ad1";
const OLD = process.env.GENERAL_MEM0_API_KEY ?? "";
const NEW = process.env.MEM0_API_KEY ?? "";
const ELEVEN = process.env.ELEVENLABS_API_KEY ?? "";
