async function list(key: string): Promise<Record<string, any>[]> {
  const res = await fetch("https://api.mem0.ai/v3/memories/?page=1&page_size=100", {
    method: "POST",
    headers: { Authorization: `Token ${key}`, "Content-Type": "application/json" },
    body: JSON.stringify({ filters: { user_id: USER } }),
  });
