  const match = /^tsubaki-([a-z]+)(-ja)?$/.exec(conv.agent_name ?? "");
  const metadata = {
    source: "elevenlabs",
    conversation_id: id,
    agent: conv.agent_name ?? "",
    persona: match?.[1] ?? "",
    lang: match?.[2] ? "ja" : "en",
