// Guarded: aborts unless exactly the 7 expected memories are there, and the new
// project still holds the migrated copies.
const USER = "tsubaki-e5d319f0-01e6-4b8c-b1f4-3bec67046ad1";
const OLD = process.env.GENERAL_MEM0_API_KEY ?? "";
const NEW = process.env.MEM0_API_KEY ?? "";
if (!OLD || !NEW || OLD === NEW) throw new Error("need distinct old and new mem0 keys");
const auth = (key: string) => ({ Authorization: `Token ${key}`, "Content-Type": "application/json" });

async function list(key: string): Promise<Record<string, any>[]> {
  const res = await fetch("https://api.mem0.ai/v3/memories/?page=1&page_size=100", {
    method: "POST",
    headers: auth(key),
    body: JSON.stringify({ filters: { user_id: USER } }),
  });
  if (!res.ok) throw new Error(`list ${res.status}`);
  return (await res.json()).results ?? [];
}

const migrated = await list(NEW);
const old = await list(OLD);
console.log(`new project: ${migrated.length} | old project: ${old.length}`);
if (migrated.length === 0) throw new Error("new project is empty; refusing to delete");
if (old.length !== 7 || old.some((m) => m.user_id !== USER)) {
  throw new Error("old project doesn't hold exactly the 7 expected memories; aborting");
}

for (const m of old) {
  const res = await fetch(`https://api.mem0.ai/v1/memories/${m.id}/`, {
    method: "DELETE",
    headers: auth(OLD),
  });
  console.log(`delete ${m.id}: ${res.status} | ${String(m.memory).slice(0, 60)}`);
}

await new Promise((r) => setTimeout(r, 3000));
console.log(`\nold project now: ${(await list(OLD)).length} | new project: ${(await list(NEW)).length}`);

