content.content:
.tb-tool {
  display: grid;
  grid-template-columns: 130px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 8px 0;
  border: 0;
  border-bottom: 1px dashed var(--hair);
  background: transparent;
  width: 100%;
  font: inherit;
  text-align: left;
  color: var(--ink);
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.08s,
    opacity 0.12s;
}
.tb-tool:hover {
  background: var(--hair-2);
}
.tb-tool.off {
  opacity: 0.55;
}
.tb-tool:last-child {
  border-bottom: 0;
}
.tb-tool-name {
  color: var(--accent);
  font-weight: 500;
}
.tb-tool-label {
  color: var(--ink-2);
}
.tb-tool-status {
  font-size: 9px;
  letter-spacing: 0.12em;
}
.tb-tools-pop-body {
  display: flex;
  flex-direction: column;
}
.tb-tools-pop-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
  padding: 8px 12px;
  border-bottom: 1px dashed var(--hair);
}
.tb-tools-pop-row:last-child {
  border-bottom: 0;
}
.tb-tools-pop-name {
  color: var(--accent);
  font-weight: 500;
  font-size: 11px;
}
.tb-tools-pop-label {
  color: var(--ink-2);
  font-size: 10px;
  text-align: right;
}

/* PREVIEW tag — a mock surface (tools). Dashed accent outline reads as "not
   live" without shouting. */
.tb-preview-tag {
  display: inline-block;
  margin-left: 8px;
  padding: 1px 5px;
  font-size: 8.5px;
  letter-spacing: 0.14em;
  line-height: 1.4;
  color: var(--accent);
  border: 1px dashed var(--accent);
  vertical-align: 1px;
  cursor: help;
}
.tsubaki[data-lang="ja"] .tb-preview-tag {
  font-size: 10px;
  letter-spacing: 0.04em;
}
.tb-transcript-scroll {
  flex: 1 1 auto;
  min-height: 0;
}
.tb-transcript-scroll .tb-scroll-area {
  padding: 0;
}
.tb-transcript-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.tb-turn {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.tb-turn-hd {
  display: flex;
  justify-content: space-between;
