  );
}

export function Tag({
  children,
  dot,
  mono,
  accent,
}: {
  children: ReactNode;
  dot?: boolean;
  mono?: boolean;
  accent?: boolean;
}) {
  const cls = ["tb-tag", mono ? "tb-tag-mono" : "", accent ? "tb-tag-accent" : ""]
