/* ── Page header ──────────────────────────────────────────────────────── */

.tb-page-hd {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
  padding: 28px 28px 18px;
  border-bottom: 1px solid var(--line);
}
.tb-page-hd-r {
  display: flex;
  gap: 8px;
  flex: 0 0 auto;
}

.tb-h-eyebrow {
  font-size: 10px;
  letter-spacing: 0.16em;
  color: var(--ink-3);
  text-transform: uppercase;
}
.tb-h1 {
  font-family: var(--tb-serif);
  font-size: 44px;
  font-weight: 400;
  letter-spacing: -0.01em;
  margin: 4px 0 6px;
  line-height: 1;
  font-style: italic;
}
.tb-lede {
  font-size: 12px;
  color: var(--ink-2);
  max-width: 56ch;
  margin: 0;
}

