const U = `tsubaki-${crypto.randomUUID()}`;
const H = { Authorization: `Token ${process.env.MEM0_API_KEY ?? ""}`, "Content-Type": "application/json" };
const ts = Math.floor(Date.parse("2026-11-10T10:00:00Z") / 1000);
const r = await fetch("https://api.mem0.ai/v3/memories/add/", { method: "POST", headers: H, body: JSON.stringify({
  user_id: U, timestamp: ts,
  messages: [{ role: "user", content: "I have a cello concert this Friday." }] }) });
console.log("add", r.status, await r.text());
for (let i = 0; i < 10; i++) {
  await new Promise((s) => setTimeout(s, 4000));
  const g = await (await fetch("https://api.mem0.ai/v3/memories/", { method: "POST", headers: H, body: JSON.stringify({ filters: { user_id: U } }) })).json();
  if (g.results?.length) { console.log(g.results.map((m: any) => [m.memory, m.created_at])); break; }
}
console.log("cleanup", (await fetch(`https://api.mem0.ai/v1/memories/?user_id=${U}`, { method: "DELETE", headers: H })).status);

