   into the transcript column, and a long label wraps inside its chip. */
.pp-call-stage { container: call-stage / inline-size; }
.pp-call-meta { gap: 8px; }
.pp-call-meta-l, .pp-call-meta-r { flex-wrap: wrap; min-width: 0; }
@container call-stage (max-width: 760px) {
  .pp-call-meta { flex-direction: column; align-items: flex-start; }
  .pp-call-meta .pp-tag { white-space: normal; overflow-wrap: anywhere; }
}

/* Tools popover: tool ids never break; the label (with its PREVIEW tag)
   wraps instead. */
.pp-tools-pop-name { white-space: nowrap; flex: 0 0 auto; }
.pp-tools-pop-label { min-width: 0; }
EOF
