import type { Metadata } from "next";
import { IBM_Plex_Mono, Newsreader } from "next/font/google";
// Japanese families are per-glyph fallbacks behind Plex Mono / Newsreader (which
// carry no CJK). They are self-hosted from Fontsource rather than next/font:
// next/font/google downloads every unicode-range slice from Google at build
// time (~620 faces for these two families), and that fetch has failed CI builds.
// Fontsource ships the same slices (124 per weight) with their unicode-range
// rules, so a browser still fetches only the slices for characters on screen,
// and plain @font-face rules are never preloaded, so English sessions load none.
// The families are bound to --font-noto-sans-jp / --font-noto-serif-jp in
// app/globals.css.
import "@fontsource/noto-sans-jp/400.css";
import "@fontsource/noto-sans-jp/500.css";
import "@fontsource/noto-sans-jp/600.css";
import "@fontsource/noto-serif-jp/400.css";
import "@fontsource/noto-serif-jp/500.css";
import "./globals.css";
import "./styles/conversations.css";
import "./styles/tweaks-dock.css";

const plexMono = IBM_Plex_Mono({
  variable: "--font-plex-mono",
  subsets: ["latin"],
  weight: ["300", "400", "500", "600"],
});

const newsreader = Newsreader({
  variable: "--font-newsreader",
  subsets: ["latin"],
  style: ["normal", "italic"],
});

export const metadata: Metadata = {
  title: "TSUBAKI — realtime voice console",
  description: "Brutalist editorial realtime voice console.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    // `lang` follows the session language at runtime (use-session-routing).
    <html lang="en" className={`${plexMono.variable} ${newsreader.variable} h-full`}>
      <body className="h-full overflow-hidden">{children}</body>
    </html>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import type { JaSans, JaSerif } from "@/lib/ja-fonts";
import { isTweaksDock, type TweaksDock } from "@/lib/tweaks-dock";

export type OrbStyle = "gradient" | "mono" | "particles";
export type TranscriptMode = "caption" | "drawer" | "off";

export interface Tweaks {
  dark: boolean;
  accent: string;
  orbStyle: OrbStyle;
  transcript: TranscriptMode;
  providerPreview: boolean;
  /**
   * Voice barge-in (OpenAI engine): let user speech interrupt the agent
   * mid-sentence. OFF by default — on speaker+mic setups the model hears its
   * own playback and truncates itself; headphone users can opt in.
   */
  voiceBargeIn: boolean;
  /**
   * Push-to-talk (cascade engine): disable Silero auto turn-end so only the
   * Send button ends your turn. OFF by default — silence ends the turn.
   */
  pushToTalk: boolean;
  /** Japanese fallback faces (see lib/ja-fonts.ts) — sans for UI, serif for display. */
  jaSans: JaSans;
  jaSerif: JaSerif;
  /** Where the floating Tweaks button docks (drag it, or pick in the panel). */
  dock: TweaksDock;
}

export const TWEAK_DEFAULTS: Tweaks = {
  dark: false,
  accent: "#B0122F",
  orbStyle: "gradient",
  transcript: "drawer",
  providerPreview: true,
  voiceBargeIn: false,
  pushToTalk: false,
  jaSans: "noto",
  jaSerif: "noto",
  dock: "bottom-right",
};

// Camellia crimson is the Tsubaki default; burnt orange (#C2410C) stays selectable.
export const ACCENTS = ["#B0122F", "#C2410C", "#2563EB", "#16A34A", "#9333EA", "#0A0A09"];

const KEY = "tsubaki.tweaks";

export function useTweaks(): [Tweaks, <K extends keyof Tweaks>(key: K, value: Tweaks[K]) => void] {
  const [tweaks, setTweaks] = useState<Tweaks>(TWEAK_DEFAULTS);

  // Hydrate from localStorage after mount to avoid SSR mismatch.
  useEffect(() => {
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) {
        const stored = JSON.parse(raw) as Partial<Tweaks>;
        // A dock name from an older build would leave the button with no position.
        if (!isTweaksDock(stored.dock)) delete stored.dock;
        setTweaks((prev) => ({ ...prev, ...stored }));
      }
    } catch {
      // ignore malformed storage
    }
  }, []);

  // Mirror dark mode to the <html> class so ElevenLabs/shadcn components follow.
  useEffect(() => {
    document.documentElement.classList.toggle("dark", tweaks.dark);
  }, [tweaks.dark]);

  const setTweak = useCallback(<K extends keyof Tweaks>(key: K, value: Tweaks[K]) => {
    setTweaks((prev) => {
      const next = { ...prev, [key]: value };
      try {
        localStorage.setItem(KEY, JSON.stringify(next));
      } catch {
        // ignore quota / privacy-mode errors
      }
      return next;
    });
  }, []);

  return [tweaks, setTweak];
}

