/* ─────────────────────────────────────────────────────────────────────────
   Tweaks dock — where the floating Tweaks button and its panel sit (the
   app's app/styles/tweaks-dock.css). Three spots; the button, the panel and
   the snap targets shown while dragging share the dock classes, so the
   geometry lives only here and the drag measures the targets.
   Positioned inside the artboard (.pp-app), not the window.
   ───────────────────────────────────────────────────────────────────────── */

.pp-app {
  position: relative;
  --pp-dock-gap: 16px;
  /* Clear the top bar (48px; 38px on the phone). */
  --pp-dock-top: calc(48px + var(--pp-dock-gap));
}
.pp-app.pp-mobile { --pp-dock-top: calc(38px + var(--pp-dock-gap)); }

.pp-dock-bottom-right { right: var(--pp-dock-gap); bottom: var(--pp-dock-gap); }
.pp-dock-top-right { right: var(--pp-dock-gap); top: var(--pp-dock-top); }
/* Bottom of the left sidebar; bottom-left on the phone (no sidebar). */
.pp-dock-sidebar { left: var(--pp-dock-gap); bottom: var(--pp-dock-gap); }

/* Docked in the sidebar, the button gets room below the sidebar footer. */
.pp-app.pp-tweaks-in-side .pp-side { padding-bottom: calc(40px + 2 * var(--pp-dock-gap)); }

.pp-tweaks-toggle {
  position: absolute; z-index: 60;
  box-sizing: border-box; width: 40px; height: 40px; padding: 0;
  appearance: none; border: 1px solid var(--line); border-radius: 0;
  background: var(--paper); color: var(--ink);
  display: flex; align-items: center; justify-content: center;
  box-shadow: 3px 3px 0 var(--line);
  cursor: grab;
  /* Pointer drags, not page scrolls or text selection, on touch screens. */
  touch-action: none; user-select: none;
}
.pp-tweaks-toggle:hover { background: var(--ink); color: var(--paper); }
.pp-tweaks-toggle.dragging {
  cursor: grabbing;
  background: var(--ink); color: var(--paper);
  box-shadow: 6px 6px 0 var(--line);
}

.pp-dock-targets { visibility: hidden; }
.pp-dock-targets.on { visibility: visible; }
.pp-dock-target {
  position: absolute; z-index: 59;
  box-sizing: border-box; width: 40px; height: 40px;
  border: 1px dashed var(--ink-3);
  pointer-events: none;
}
.pp-dock-target.hit {
  border: 1px solid var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}

/* The open panel grows away from its corner; it scrolls if the artboard is
   too short for it. */
.pp-tweaks {
  position: absolute; z-index: 60;
  width: 280px; max-height: calc(100% - var(--pp-dock-top) - var(--pp-dock-gap));
