  1	"use client";
  2	
  3	// Conversation history for the Conversations view: the visitor's stored calls
  4	// (paged) and the one selected for reading. Loaded when the view mounts, so the
  5	// list is fresh each visit; ElevenLabs needs a minute after hangup before a
  6	// call is listed.
  7	
  8	import { useCallback, useEffect, useRef, useState } from "react";
  9	import {
 10	  HistoryError,
 11	  fetchConversationDetail,
 12	  fetchConversationPage,
 13	} from "@/lib/conversations/client";
 14	import type { ConversationDetail, ConversationSummary } from "@/lib/conversations/types";
 15	import { getMemoryUserId } from "@/lib/memory/user-id";
 16	
 17	/** Why a load failed, in terms the view can phrase: missing key, or anything else. */
 18	export type HistoryFailure = "unconfigured" | "failed";
 19	
 20	export interface ConversationsState {
 21	  items: ConversationSummary[];
 22	  loading: boolean;
 23	  failure: HistoryFailure | null;
 24	  hasMore: boolean;
 25	  loadMore: () => void;
 26	  reload: () => void;
 27	  selectedId: string | null;
 28	  select: (id: string) => void;
 29	  detail: ConversationDetail | null;
 30	  detailLoading: boolean;
 31	  detailFailure: HistoryFailure | null;
 32	}
 33	
 34	function failureOf(err: unknown): HistoryFailure | null {
 35	  if (err instanceof DOMException && err.name === "AbortError") return null;
 36	  return err instanceof HistoryError && err.status === 503 ? "unconfigured" : "failed";
 37	}
 38	
 39	function useConversationList() {
 40	  const [items, setItems] = useState<ConversationSummary[]>([]);
 41	  const [cursor, setCursor] = useState<string | null>(null);
 42	  const [loading, setLoading] = useState(true);
 43	  const [failure, setFailure] = useState<HistoryFailure | null>(null);
 44	  const abortRef = useRef<AbortController | null>(null);
 45	
 46	  const load = useCallback((from: string | null) => {
 47	    abortRef.current?.abort();
 48	    const ctrl = new AbortController();
 49	    abortRef.current = ctrl;
 50	    setLoading(true);
 51	    setFailure(null);
 52	    fetchConversationPage(getMemoryUserId(), from, ctrl.signal)
 53	      .then((page) => {
 54	        setItems((prev) => (from ? [...prev, ...page.items] : page.items));
 55	        setCursor(page.nextCursor);
 56	        setLoading(false);
 57	      })
 58	      .catch((err: unknown) => {
 59	        const f = failureOf(err);
 60	        if (f === null) return; // superseded by a newer load
 61	        setFailure(f);
 62	        setLoading(false);
 63	      });
 64	  }, []);
 65	
 66	  useEffect(() => {
 67	    load(null);
 68	    return () => abortRef.current?.abort();
 69	  }, [load]);
 70	
 71	  return {
 72	    items,
 73	    loading,
 74	    failure,
 75	    hasMore: cursor !== null,
 76	    loadMore: () => cursor && !loading && load(cursor),
 77	    reload: () => load(null),
 78	  };
 79	}
 80	
 81	function useConversationDetail(selectedId: string | null) {
 82	  const cache = useRef(new Map<string, ConversationDetail>());
 83	  const [detail, setDetail] = useState<ConversationDetail | null>(null);
 84	  const [loading, setLoading] = useState(false);
 85	  const [failure, setFailure] = useState<HistoryFailure | null>(null);
 86	
 87	  useEffect(() => {
 88	    if (!selectedId) return;
 89	    const hit = cache.current.get(selectedId);
 90	    setDetail(hit ?? null);
 91	    setFailure(null);
 92	    setLoading(!hit);
 93	    if (hit) return;
 94	    const ctrl = new AbortController();
 95	    fetchConversationDetail(getMemoryUserId(), selectedId, ctrl.signal)
 96	      .then((d) => {
 97	        cache.current.set(d.id, d);
 98	        setDetail(d);
 99	        setLoading(false);
100	      })
101	      .catch((err: unknown) => {
102	        const f = failureOf(err);
103	        if (f === null) return;
104	        setFailure(f);
105	        setLoading(false);
106	      });
107	    return () => ctrl.abort();
108	  }, [selectedId]);
109	
110	  return { detail, loading, failure };
111	}
112	
113	export function useConversations(initialId: string | null = null): ConversationsState {
114	  const list = useConversationList();
115	  const [selectedId, setSelectedId] = useState<string | null>(initialId);
116	  const { detail, loading, failure } = useConversationDetail(selectedId);
117	  return {
118	    ...list,
119	    selectedId,
120	    select: setSelectedId,
121	    detail,
122	    detailLoading: loading,
123	    detailFailure: failure,
124	  };
125	}

